/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * M1's firmware: check that startup gave C its memory, write the marker,
 * measure the core clock, then run on a 1 ms tick interrupt that keeps
 * the heartbeat, idling in between.
 */

#include "sb.h"
#include "WL82.h"

/* HW-25: in fwtest each word written here is appended to the console. The
 * SDK declares DBG_MSG read-only (Q-5), so it is written through our own
 * pointer rather than the SDK's struct. */
#define DBG_MSG (*(volatile u32 *)0x01EEE244u)

/* HW-13: TIMER4 counts 24 MHz once CON bit 0 is set: the time base. */
#define TIMER4_RUN   0x1u
#define TICKS_PER_MS 24000u

/* HW-16: TIMER0 runs with CON bits 0-1 non-zero, bits 4-7 = 2 divide the
 * 24 MHz clock by 16, and it interrupts on reaching PRD: 1500 counts of
 * 1.5 MHz is 1 ms. Writing CON with bit 14 acknowledges it. */
#define TICK_CON     0x21u
#define TICK_ACK     (1u << 14)
#define TICK_PRD     1500u

extern u32 __stack_limit[], __irq_stack_top[];

volatile struct sb_beacon sb_beacon __attribute__((section(".beacon")));

/* One of each kind of C data, for main to check that sb_start copied and
 * cleared them. */
static volatile u32 data_probe = 0x5EED0001u;
static volatile u32 bss_probe;

/* The heartbeat's state, kept by sb_tick: the time base when main started
 * it, the ticks counted into beats so far, the time base at the last
 * tick. */
static u32 tb_start, tb_done, tb_last;

void sb_console_write(const char *text, u32 words)
{
    while (words--) {
        const u8 *b = (const u8 *)text;
        DBG_MSG = (u32)b[0] | (u32)b[1] << 8 | (u32)b[2] << 16 | (u32)b[3] << 24;
        text += 4;
    }
}

/* The tick. The heartbeat counts whole milliseconds of the time base, not
 * ticks, so it stays exact whatever the tick's own period does (our fwtest
 * runs measure TIMER0's 1 ms as 24 000.7 time base ticks: DESIGN-NOTES.md,
 * M1); the ticks and their intervals are counted on the side. */
void sb_tick(void)
{
    u32 now = JL_TIMER4->CNT - tb_start;
    u32 n = sb_beacon.tick_count, beats;

    JL_TIMER0->CON = TICK_CON | TICK_ACK;
    sb_beacon.seq++;
    if (n) {
        u32 d = now - tb_last;
        if (n == 1 || d < sb_beacon.interval_min)
            sb_beacon.interval_min = d;
        if (d > sb_beacon.interval_max)
            sb_beacon.interval_max = d;
    }
    tb_last = now;
    sb_beacon.tick_count = n + 1;
    /* Every whole millisecond that has passed, so a late tick still leaves
     * the right count. Unsigned differences stay right across a wrap. */
    beats = sb_beacon.beats;
    while (now - tb_done >= TICKS_PER_MS) {
        tb_done += TICKS_PER_MS;
        beats++;
#if defined(SB_PROBE_SLOW)
        sb_probe_slow();
#endif
    }
    sb_beacon.beats = beats;
    sb_beacon.ticks = now;
    sb_beacon.beats_b = beats;
    sb_beacon.ticks_b = now;
    sb_beacon.seq++;

    /* Each stack's lowest word still holds the fill: nothing ran past it. */
    if (__irq_stack_top[0] != SB_STACK_FILL)
        sb_halt(SB_HALT_STACK, 1, 0);
    if (__stack_limit[0] != SB_STACK_FILL)
        sb_halt(SB_HALT_STACK, 2, 0);
}

int main(void)
{
    static const char hello[16] = "small-beeps M1 \n";

    sb_beacon.period = TICKS_PER_MS;
    if (data_probe == 0x5EED0001u && bss_probe == 0) {
        sb_beacon.marker = SB_MARKER;
        sb_console_write(hello, sizeof hello / 4);
    } else {
        sb_beacon.marker = SB_MARKER_BAD;
    }

    /* Only differences of CNT are used: its value when started, and its
     * response to writes, don't matter. */
    JL_TIMER4->CON = TIMER4_RUN;
    tb_start = JL_TIMER4->CNT;
    /* No clock register is written (HW-11, SR-2): the clock is measured. */
    sb_beacon.clock = sb_clock_measure((volatile u32 *)&JL_TIMER4->CNT);
#if defined(SB_PROBE_BIG)
    sb_probe_big();
#endif
#if defined(SB_PROBE_STACK)
    sb_probe_stack();
#endif

    sb_irq_init(sb_tick);
    JL_TIMER0->CNT = 0;
    JL_TIMER0->PRD = TICK_PRD;
    JL_TIMER0->CON = TICK_CON;
    sb_irq_on();

#if defined(SB_TEST_FAULT)
    sb_test_fault();
#endif
#if defined(SB_TEST_STRAY)
    sb_test_stray();
#endif
#if defined(SB_TEST_BADINSN)
    sb_test_badinsn();
#endif
    /* Everything happens in sb_tick; between ticks the core waits. */
    for (;;) {
        __asm__ volatile("idle");
        sb_beacon.wakes++;
    }
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Interrupts: our own vector table, which sources are enabled, and the
 * one way out when something goes wrong: report and halt.
 */

#include "sb.h"
#include "WL82.h"

/* HW-18: the handler of source n is the word at __vectors + 4n (app.ld). */
_Static_assert(sizeof(unsigned short) == 2, "a stub is 2 bytes");
extern volatile u32 __vectors[];
#define SOURCES 128

/* crt0.S: one 2-byte stub per source, in source order. */
extern const unsigned short sb_irq_stubs[];

/* HW-19 and the SDK's hwi.h (P-16): the sources M1 handles. Sources 0 to
 * 2 are the debug, exception and system-call sources, the CPU's own
 * faults: their stubs report a fault rather than a stray interrupt. */
#define SRC_EXCEPTION   1u
#define SRC_LAST_FAULT  2u
#define SRC_TIMER0      4u

/* HW-20: 4 bits a source in ICFG00-ICFG31, bit 0 enable, bits 1-3 the
 * priority (higher wins). Only the tick and the exception source are
 * enabled; nothing nests (DESIGN-NOTES.md, M1). */
#define PRIO_TICK   1u
#define PRIO_FAULT  7u
#define ICFG_BITS(src, prio)  ((1u | (prio) << 1) << 4 * ((src) % 8))
#define ICFG_WORDS  32

/* HW-21: the master enable in the core register icfg. */
#define ICFG_MASTER (1u << 8)

void sb_irq_unexpected(u32 source, u32 reti) __attribute__((noreturn));

void sb_irq_init(void (*tick)(void))
{
    volatile u32 *icfg = &q32DSP(0)->ICFG00;
    u32 n;

    for (n = 0; n < SOURCES; n++)
        __vectors[n] = (u32)&sb_irq_stubs[n];
    __vectors[SRC_TIMER0] = (u32)tick;

    /* Every word written, so nothing a loader left enabled stays so. Both
     * sources M1 enables are in the first word. */
    _Static_assert(SRC_EXCEPTION / 8 == 0 && SRC_TIMER0 / 8 == 0, "both in ICFG00");
    icfg[0] = ICFG_BITS(SRC_EXCEPTION, PRIO_FAULT) | ICFG_BITS(SRC_TIMER0, PRIO_TICK);
    for (n = 1; n < ICFG_WORDS; n++)
        icfg[n] = 0;
}

/* HW-21: both gates, icfg's bit 8 and sti. */
void sb_irq_on(void)
{
    u32 cfg;

    __asm__ volatile("%0 = icfg" : "=r"(cfg));
    cfg |= ICFG_MASTER;
    __asm__ volatile("icfg = %0" :: "r"(cfg));
    __asm__ volatile("sti");
}

/* From crt0.S's stubs: an interrupt with no handler of its own. */
void sb_irq_unexpected(u32 source, u32 reti)
{
    sb_halt(source <= SRC_LAST_FAULT ? SB_HALT_FAULT : SB_HALT_STRAY, source, reti);
}

static const char reasons[3][5] = { "stray", "fault", "stack" };
static const char hex[16] = "0123456789abcdef";

/* Records why in the beacon, writes one console line, "HALT <reason>
 * <source in hex> ", and stops: interrupts off and a jump to itself,
 * which fwtest reports as a halt (docs/HARNESS.md). Nothing is resumed. */
void sb_halt(u32 reason, u32 source, u32 reti)
{
    char line[16] = "HALT ..... 000 \n";
    u32 i;

    __asm__ volatile("cli");
    sb_beacon.halt_source = source;
    sb_beacon.halt_reti = reti;
    sb_beacon.halt_reason = reason;
    for (i = 0; i < 5; i++)
        line[5 + i] = reasons[reason - 1][i];
    line[11] = hex[source >> 8 & 0xF];
    line[12] = hex[source >> 4 & 0xF];
    line[13] = hex[source & 0xF];
    sb_console_write(line, sizeof line / 4);
    for (;;)
        ;
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * C runtime start: give C its initial memory, then run main. Called from
 * crt0.S on the stack it set up. The symbols come from firmware/app.ld.
 */

#include "sb.h"

extern u32 __data_load[], __data_start[], __data_end[];
extern u32 __bss_start[], __bss_end[];

void sb_start(void) __attribute__((noreturn));

void sb_start(void)
{
    const u32 *src = __data_load;
    u32 *dst;

    /* Initialised data: its bytes sit in the image, after the code. */
    for (dst = __data_start; dst < __data_end; dst++)
        *dst = *src++;

    /* Zero-initialised data. fwtest starts with RAM cleared, but a loader
     * on the chip makes no such promise. */
    for (dst = __bss_start; dst < __bss_end; dst++)
        *dst = 0;

    main();
}

