def probe_budgets(ref, probe, budgets, from_ref):
    """budgets with each limit set to a measurement: the unmodified
    build's (ref) for the budgets in from_ref, the probe's own otherwise.
    The steady-state limit is rounded down, so a probe's own steady state
    passes it only when it is a whole number (rounded up instead)."""
    def limit(m, k):
        v = budget_value(m, k)
        if k == "steady_per_period":
            return int(v) if m is ref else -(-v.numerator // v.denominator)
        return v
    return {"milestone": "probe", "limits": {k: limit(ref if k in from_ref else probe, k) for k in BUDGETED},
            "speed_rise_percent": budgets["speed_rise_percent"]}

