 * is above SPI1's, so a tick waits at most for one short SPI1 handler
 * (DESIGN-NOTES.md, M2). */
#define SRC_TIMER0   4u
#define SRC_SPI1     16u
#define PRIO_TICK    1u
#define PRIO_SPI1    0u

