            self.assertTrue(fw.check_test_screen(broken))
        missing_edge = [list(r) for r in rows]
        missing_edge[239][120] = (0, 0, 0)
        self.assertTrue(any("edge" in p for p in fw.check_test_screen(missing_edge)))
